use serde_json::{json,Value};use std::{fs,path::Path,process::Command};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn raw(args:&[&str])->std::process::Output{Command::new("aws").args(["--profile","dev","--region","eu-north-1","--no-cli-pager"]).args(args).output().unwrap()}
fn main(){let r=Path::new("/tmp/zopro-ready-c7a");let iid=fs::read_to_string(r.join("instance-id.txt")).unwrap();let observed=read(r.join("termination-observation.json"));assert_eq!(observed["Reservations"][0]["Instances"][0]["InstanceId"],iid.trim());assert_eq!(observed["Reservations"][0]["Instances"][0]["State"]["Name"],"terminated");assert!(read(r.join("volume-observation.json"))["Volumes"].as_array().unwrap().is_empty());assert!(read(r.join("ecr-cleanup.json"))["failures"].as_array().unwrap().is_empty());let im=read(r.join("image-manifest.json"));let tag=im["image_tag"].as_str().unwrap().rsplit(':').next().unwrap();let ecr=raw(&["ecr","describe-images","--repository-name","zolana-prover","--image-ids",&format!("imageTag={tag}")]);assert!(!ecr.status.success());assert!(String::from_utf8_lossy(&ecr.stderr).contains("ImageNotFoundException"));let bucket=read(r.join("bucket.json"));let head=raw(&["s3api","head-bucket","--bucket",bucket["name"].as_str().unwrap()]);assert!(!head.status.success());assert!(String::from_utf8_lossy(&head.stderr).contains("404"));assert!(!r.join("upload-parameters.secret.json").exists());let live=raw(&["ec2","describe-instances","--filters","Name=tag:Purpose,Values=TemporaryProverBenchmark","Name=instance-state-name,Values=pending,running,stopping,stopped"]);assert!(live.status.success());let live:Value=serde_json::from_slice(&live.stdout).unwrap();assert!(live["Reservations"].as_array().unwrap().is_empty());let out=json!({"status":"complete","owned_instance":iid.trim(),"instance_state":"terminated","owned_volumes_present":0,"owned_ECR_tag_absent":true,"owned_transfer_object_and_bucket_absent":true,"private_presigned_parameter_file_deleted":true,"all_live_TemporaryProverBenchmark_instances_in_region":0,"production_services_roles_and_networking_unchanged":true});fs::write(r.join("cleanup-complete.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Cleanup verified: instance terminated; volume, ECRtag and transfer bucket absent; zero live temporary benchmark instances");}
